    /// <summary>
    /// Names of the functions and variables Xbox 360 system modules export by ordinal (a XEX imports by ordinal only).
    /// Generated from the export tables of the Xenia project (BSD licence, Copyright Ben Vanik - see About).
    /// </summary>
    public static class XexImportNames
    {
        private static readonly Dictionary<string, Dictionary<int, string>> Tables = new Dictionary<string, Dictionary<int, string>>(StringComparer.OrdinalIgnoreCase);

        /// <summary>The name of ordinal <paramref name="ordinal"/> of a library such as "xboxkrnl.exe" or "xam.xex", or null when unknown.</summary>
        public static string Find(string library, int ordinal)
        {
            string key = (library ?? "").ToLowerInvariant();
            int dot = key.IndexOf('.');
            if (dot > 0) key = key.Substring(0, dot);
            Dictionary<int, string> table;
            lock (Tables)
            {
                if (!Tables.TryGetValue(key, out table))
                {
                    string packed = key == "xboxkrnl" ? Xboxkrnl : key == "xam" ? Xam : key == "xbdm" ? Xbdm : "";
                    table = new Dictionary<int, string>();
                    foreach (string item in packed.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                        int eq = item.IndexOf('=');
                        table[Convert.ToInt32(item.Substring(0, eq), 16)] = item.Substring(eq + 1);
                    }
                    Tables[key] = table;
                }
            }
            return table.TryGetValue(ordinal, out string name) ? name : null;
        }

